// Fresh KDS kitchen-display integration — paid website orders are ALSO
// sent to the restaurant's Fresh KDS screens (the site's own /kitchen
// page keeps working exactly as before; this is an extra screen feed).
//
// COMPLETE NO-OP UNTIL CONFIGURED: everything in this file is inert
// unless FRESHKDS_TOKEN is set in the environment (Vercel). The token
// is generated by the owner in the Fresh KDS web portal
// (Settings -> Integration Tokens) and is entered in Vercel by the
// owner only — it never appears in code, chat, or the admin panel.
//
// API contract (Fresh KDS official integrator docs,
// https://www.fresh.technology/kds/developer-guide and the API
// reference at fresh-technology.github.io/fresh.kds.docs.mobile-local-network-integration):
//   Base (production): https://integrations-api.ftservices.cloud
//   Base (sandbox):    https://sandbox-integrations-api.ftservices.cloud
//   Auth: EVERY request carries header  x-integration-token: <token>
//   Send order: POST /integrators/kds-orders with headers
//     x-location-id: <location uuid>   x-device-ids: all
//   Body (KDS Order): id (unique string), name, time (ISO 8601),
//     mode — one of "For Here" | "ToGo" | "Pickup" | "DriveThru" |
//     "Delivery" | "Curbside" — and items[] of
//     { lineId, name, qty, price (STRING, may include "$"), mods:
//       [{ name, qty }] (array REQUIRED, empty when no modifiers),
//       specialInstructions }.
//     Costs are an object of STRINGS: subtotal, tax, deliveryFee,
//     tip, total, additionalFees [{name, amount}], promoCodes.
//   Success is 201 Created; re-sending an existing id is 409 Conflict
//   (treated here as "already on the screens").
//   Locations: GET /integrators/kds-information/locations returns a
//     top-level array; each location's id field is `id`.
//
// SMS RULE: optInForSms is ALWAYS false. Customers get their order
// texts from THIS site (Twilio, lib/sms.ts) — Fresh KDS must never
// text them.
//
// Best-effort by design: sendOrderToFreshKds never throws; the result
// is recorded on the order (orders.freshkds_status / freshkds_error /
// freshkds_sent_at, added by supabase/freshkds-schema.sql) and shown
// in the admin order detail. All reads/writes of those columns are
// wrapped so the site works before the SQL runs.

import { getServiceClient } from "./supabase/server";
import { normalizePhone } from "./shipday";
import { formatCents, MENU_BY_ID } from "./menu";
import { getPricingMenuById } from "./menuDb";
import { freshKdsMode } from "./fulfillment";

const DEFAULT_API_BASE = "https://integrations-api.ftservices.cloud";

/** One stored order line (the real shape written by lib/pricing.ts). */
export interface FreshKdsLine {
  id: string;
  name: string;
  qty: number;
  unit_price_cents: number;
  line_total_cents: number;
  options?: { group?: string; name: string; price_delta_cents?: number }[];
  instructions?: string;
}

/** The slice of an orders row this integration needs. */
export interface FreshKdsOrder {
  id: number;
  customer_name: string | null;
  customer_phone: string | null;
  fulfillment: string;
  delivery_address: string | null;
  items_json: FreshKdsLine[];
  subtotal_cents: number;
  discount_cents?: number;
  service_fee_cents?: number;
  tax_cents: number;
  delivery_fee_cents: number;
  delivery_markup_cents?: number;
  free_delivery?: boolean;
  tip_cents: number;
  total_cents: number;
  created_at: string;
  scheduled_for?: string | null;
  delivery_external_id?: string | null;
  freshkds_status?: string | null;
}

export function freshkdsConfigured(): boolean {
  return Boolean(process.env.FRESHKDS_TOKEN);
}

// ---- ON/OFF switch (Admin → Operations → "Fresh KDS screen") -------------------
//
// Stored as the site_settings key `freshkds_enabled`. FAIL-SOFT RULE:
// a missing key, a missing table or any DB error reads as ON, so the
// switch can never silently stop the kitchen screens — only an
// explicit `false` saved by the admin turns sends off. When OFF,
// markOrderPaid's send records freshkds_status 'off' on the order
// instead of calling the Fresh API (see sendOrderToFreshKds).

const FRESHKDS_ENABLED_KEY = "freshkds_enabled";

/** Pure: only an explicit false / "false" means OFF; anything else is ON. */
export function freshkdsEnabledFromValue(value: unknown): boolean {
  return !(value === false || value === "false");
}

export async function getFreshKdsEnabled(): Promise<boolean> {
  try {
    const supabase = getServiceClient();
    const { data, error } = await supabase
      .from("site_settings")
      .select("value")
      .eq("key", FRESHKDS_ENABLED_KEY)
      .maybeSingle();
    if (error || !data) return true;
    return freshkdsEnabledFromValue((data as { value: unknown }).value);
  } catch {
    return true;
  }
}

export async function setFreshKdsEnabled(enabled: boolean): Promise<void> {
  const supabase = getServiceClient();
  const { error } = await supabase
    .from("site_settings")
    .upsert(
      {
        key: FRESHKDS_ENABLED_KEY,
        value: enabled === true,
        updated_at: new Date().toISOString(),
      },
      { onConflict: "key" }
    );
  if (error) throw error;
}

function apiBase(): string {
  return (process.env.FRESHKDS_API_BASE || DEFAULT_API_BASE).replace(/\/+$/, "");
}

function authHeaders(): Record<string, string> {
  return {
    "Content-Type": "application/json",
    Accept: "application/json",
    "x-integration-token": process.env.FRESHKDS_TOKEN ?? "",
  };
}

// ---- Location discovery -------------------------------------------------------

let cachedLocationId: string | null = null;

/**
 * The Fresh KDS location orders go to: FRESHKDS_LOCATION_ID when set,
 * otherwise the FIRST location returned by the locations endpoint
 * (this brand has one restaurant). Cached for the process lifetime.
 */
export async function resolveLocationId(): Promise<string> {
  if (cachedLocationId) return cachedLocationId;
  const fromEnv = process.env.FRESHKDS_LOCATION_ID?.trim();
  if (fromEnv) {
    cachedLocationId = fromEnv;
    return fromEnv;
  }
  const res = await fetch(`${apiBase()}/integrators/kds-information/locations`, {
    method: "GET",
    headers: authHeaders(),
    signal: AbortSignal.timeout(10_000),
  });
  if (!res.ok) {
    throw new Error(`Fresh KDS locations lookup failed (HTTP ${res.status})`);
  }
  const data: unknown = await res.json().catch(() => null);
  const first = Array.isArray(data) ? data[0] : undefined;
  const id =
    first && typeof first === "object"
      ? (first as { id?: unknown; locationId?: unknown }).id ??
        (first as { locationId?: unknown }).locationId
      : undefined;
  if (id === undefined || id === null || String(id) === "") {
    throw new Error("Fresh KDS returned no locations for this token");
  }
  cachedLocationId = String(id);
  return cachedLocationId;
}

// ---- Payload mapping ------------------------------------------------------------

/**
 * Build the Fresh KDS "KDS Order" body for one paid order.
 * Pure function (no env, no network) so it can be eyeballed in tests.
 */
export function buildFreshKdsPayload(
  order: FreshKdsOrder,
  numbers?: Record<string, string>
): Record<string, unknown> {
  const isDelivery = order.fulfillment === "delivery";

  // Customer-facing delivery charge = the ONE merged line the customer
  // paid (pure DoorDash fee + admin markup), $0 under Free Delivery.
  const deliveryChargeCents = !isDelivery
    ? 0
    : order.free_delivery
      ? 0
      : order.delivery_fee_cents + (order.delivery_markup_cents ?? 0);

  const costs: Record<string, unknown> = {
    subtotal: formatCents(order.subtotal_cents),
    tax: formatCents(order.tax_cents),
    total: formatCents(order.total_cents),
  };
  if (isDelivery) costs.deliveryFee = formatCents(deliveryChargeCents);
  if (order.tip_cents > 0) costs.tip = formatCents(order.tip_cents);
  if ((order.service_fee_cents ?? 0) > 0) {
    costs.additionalFees = [
      { name: "Service fee", amount: formatCents(order.service_fee_cents ?? 0) },
    ];
  }
  if ((order.discount_cents ?? 0) > 0) {
    costs.promoCodes = [
      { name: "Loyalty discount", amount: formatCents(-(order.discount_cents ?? 0)) },
    ];
  }

  const payload: Record<string, unknown> = {
    // Unique per location; our order ids are unique, and a re-send of
    // the same id returns 409 (handled as already-sent).
    id: String(order.id),
    name: order.customer_name?.trim() || `Order #${order.id}`,
    // Appended to the displayed order name by Fresh KDS — lets the
    // kitchen match the screen card to our order number.
    checkNumber: String(order.id),
    time: order.created_at || new Date().toISOString(),
    // "Pickup" | "Curbside" | "Delivery" (lib/fulfillment) — curbside
    // orders ride to the screens as Curbside, with no delivery data.
    mode: freshKdsMode(order.fulfillment),
    terminal: "Madinah Market website",
    onlineOrder: true,
    isPaid: true,
    // ALWAYS false — this site sends its own Twilio texts.
    optInForSms: false,
    items: (order.items_json ?? []).map((line, i) => {
      // Per-unit price INCLUDING chosen options (line_total is an
      // exact multiple of qty by construction in lib/pricing.ts).
      const unitWithOptions =
        line.qty > 0 ? Math.round(line.line_total_cents / line.qty) : line.line_total_cents;
      // The kitchen knows dishes by their menu numbers — prefix the
      // number exactly as the website shows it ("#13 Sultani Kabob").
      const num = numbers?.[line.id];
      const item: Record<string, unknown> = {
        lineId: String(i + 1),
        name: num && !line.name.startsWith("#") ? `${num} ${line.name}` : line.name,
        qty: line.qty,
        price: formatCents(unitWithOptions),
        mods: (line.options ?? []).map((o) => ({ name: o.name, qty: 1 })),
      };
      if (line.instructions?.trim()) {
        item.specialInstructions = line.instructions.trim();
      }
      return item;
    }),
    costs,
  };

  const phone = normalizePhone(order.customer_phone ?? "");
  if (phone.startsWith("+") && phone.replace(/\D/g, "").length >= 10) {
    payload.phoneNumber = phone;
  }
  if (isDelivery && order.delivery_address) {
    payload.deliveryAddress = order.delivery_address;
  }
  if (order.scheduled_for) {
    payload.pickupTime = order.scheduled_for;
  }
  if (isDelivery && order.delivery_external_id) {
    payload.deliveryService = {
      name: "DoorDash",
      orderId: order.delivery_external_id,
    };
  }
  return payload;
}

// ---- Result recording (fail-soft until the schema SQL runs) ----------------------

async function recordFreshKdsResult(
  orderId: number,
  status: "sent" | "failed" | "off",
  error: string | null
): Promise<void> {
  try {
    const supabase = getServiceClient();
    const { error: dbError } = await supabase
      .from("orders")
      .update({
        freshkds_status: status,
        freshkds_error: error,
        freshkds_sent_at: status === "sent" ? new Date().toISOString() : null,
      })
      .eq("id", orderId);
    if (dbError) {
      console.error(
        "[freshkds] could not record the result (has supabase/freshkds-schema.sql run?):",
        dbError.message
      );
    }
  } catch (err) {
    console.error("[freshkds] recording the result failed:", err);
  }
}

// ---- Send -------------------------------------------------------------------------

/**
 * Send one paid order to the Fresh KDS screens. NEVER throws and is a
 * complete no-op until FRESHKDS_TOKEN is set. Called from
 * markOrderPaid on the first paid transition only, so each order is
 * sent once; the freshkds_status guard + the API's 409 make any
 * accidental second attempt harmless.
 */
export async function sendOrderToFreshKds(
  order: FreshKdsOrder
): Promise<{ ok: boolean; detail: string }> {
  if (order.freshkds_status === "sent") return { ok: true, detail: "already sent" };
  // ON/OFF switch (Admin → Operations): when OFF the Fresh API is
  // never called and the order records status 'off', so the admin
  // order detail can show exactly why nothing was sent. The gate is
  // checked before the configured check so 'off' is recorded even on
  // a not-yet-configured install. Fail-soft: an unreadable setting
  // reads as ON (getFreshKdsEnabled).
  if (!(await getFreshKdsEnabled())) {
    await recordFreshKdsResult(order.id, "off", null);
    return { ok: false, detail: "off — KDS switch is OFF" };
  }
  if (!freshkdsConfigured()) return { ok: false, detail: "not configured" };
  try {
    const locationId = await resolveLocationId();
    // Menu numbers for the item names: live menu (DB) first, the
    // built-in menu as fallback. Fail-soft — no numbers, plain names.
    const numbers: Record<string, string> = {};
    try {
      const byId = await getPricingMenuById();
      for (const [id, item] of Object.entries(byId)) {
        if (item.number) numbers[id] = item.number;
      }
    } catch {
      /* fall through to the built-in menu */
    }
    if (Object.keys(numbers).length === 0) {
      for (const [id, item] of Object.entries(MENU_BY_ID)) {
        if (item.number) numbers[id] = item.number;
      }
    }
    const res = await fetch(`${apiBase()}/integrators/kds-orders`, {
      method: "POST",
      headers: {
        ...authHeaders(),
        "x-location-id": locationId,
        "x-device-ids": "all",
      },
      body: JSON.stringify(buildFreshKdsPayload(order, numbers)),
      signal: AbortSignal.timeout(10_000),
    });
    if (res.status === 201 || res.ok) {
      await recordFreshKdsResult(order.id, "sent", null);
      return { ok: true, detail: "sent" };
    }
    if (res.status === 409) {
      // This order id is already on the screens — that IS success for
      // an idempotent re-send.
      await recordFreshKdsResult(order.id, "sent", null);
      return { ok: true, detail: "already on screens" };
    }
    const text = await res.text().catch(() => "");
    let message = `Fresh KDS HTTP ${res.status}`;
    try {
      const parsed = JSON.parse(text) as { message?: unknown };
      if (typeof parsed?.message === "string" && parsed.message) {
        message = parsed.message;
      }
    } catch {
      // Non-JSON error body — keep the HTTP status message.
    }
    message = message.slice(0, 300);
    await recordFreshKdsResult(order.id, "failed", message);
    console.error(`[freshkds] order ${order.id} rejected:`, message);
    return { ok: false, detail: message };
  } catch (err) {
    const message = (err instanceof Error ? err.message : "network error").slice(0, 300);
    await recordFreshKdsResult(order.id, "failed", message);
    console.error(`[freshkds] order ${order.id} send failed:`, err);
    return { ok: false, detail: message };
  }
}
